"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def multiplyMatrices(A, B, rowsA, colsA, colsB):
    # Assumes A is rowsA x colsA, B is colsA x colsB
    result = [[0 for _ in range(colsB)] for _ in range(rowsA)]
    for i in range(0, rowsA):
        for j in range(0, colsB):
            sum = 0
            for k in range(0, colsA):
                sum = (sum + (A[i][k] * B[k][j]))
            result[i][j] = sum
    return result
print(multiplyMatrices([[1, 2], [3, 4]], [[5, 6], [7, 8]], 2, 2, 2))
